            ("затруднять", "to make difficult, to hinder", "затруднять контроль"),
            ("воспроизвести / воспроизводить", "to reproduce", "воспроизвести ошибку"),
            ("ткач", "weaver", "английские ткачи"),
            ("переобуче'ние", "retraining", "программы переобуче'ния"),
            ("неравномерно", "unevenly", "развиваться неравномерно"),
